t.script:
document.addEventListener('DOMContentLoaded', function() {

  async function handleClick(e) {
    e.preventDefault();
    const btn = e.target;
    const url = btn.getAttribute('href');
    const card = btn.closest('.card, tr');

    btn.disabled = true;
    const originalText = btn.textContent;
    btn.textContent = 'Processing...';

    try {
      const response = await fetch(url, { method: 'GET' });
      const result = await response.json();

      if (!result.success) {
        alert(result.message || 'Error processing request');
        btn.disabled = false;
        btn.textContent = originalText;
        return;
      }

      // ✅ UI Update
      if (btn.classList.contains('btn-checkin')) {
        // Switch to checkout state
        btn.classList.remove('btn-success', 'btn-checkin');
        btn.classList.add('btn-warning', 'btn-checkout');
        btn.textContent = 'Check-out';
        btn.setAttribute('href', url.replace('checkin', 'checkout'));
        updateStatus(card, 'Checked In', 'bg-success');

      } else if (btn.classList.contains('btn-checkout')) {
        // After checkout, remove button
        btn.remove();

        // Add “No Action” for desktop
        const actionCell = card.querySelector('td:last-child');
        if (actionCell) {
          const noAction = document.createElement('span');
          noAction.className = 'text-muted small';
          noAction.textContent = 'No Action';
          actionCell.appendChild(noAction);
        }

        updateStatus(card, 'Checked Out', 'bg-warning text-dark');
      }

    } catch (err) {
      alert('Error: ' + err.message);
      btn.disabled = false;
      btn.textContent = originalText;
    }
  }

  // 🧩 Update the status cell or paragraph
  function updateStatus(card, newText, newClass) {
    // 🖥️ Desktop table (td:nth-child(6) = Status column)
    const statusCell = card.querySelector('td:nth-child(6)');
    if (statusCell) {
      statusCell.innerHTML = `${newText}`;
      return;
    }

    // 📱 Mobile card (Status paragraph)
    const pTags = card.querySelectorAll('p');
    pTags.forEach(p => {
      if (p.textContent.includes('Status')) {
        let span = p.querySelector('span');
        if (!span) {
          span = document.createElement('span');
          p.appendChild(span);
        }
        span.textContent = newText;
        span.className = 'badge ' + newClass;
      }
    });
  }

  // Attach events to all buttons
  document.querySelectorAll('a.btn-success, a.btn-warning').forEach(btn => {
    btn.classList.add(
      btn.textContent.includes('Check-in') ? 'btn-checkin' : 'btn-checkout'
    );
    btn.addEventListener('click', handleClick);
  });
});
